package org.memphiszoo.custodial.vault;
import static org.junit.Assert.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.json.JSONObject;
import org.junit.Test;

/** NEW pure DTO challenges and exact retained actual-SQL shape parity only.
 * Neither synthetic rows nor this parser establish auth, current custody,
 * semantic ACK, all namespace values, Android, HTTP, key or release proof. */
public final class NativePrivateCustodyReadbackTest {
    static final String OP="11111111-1111-4111-8111-111111111111",GEN="22222222-2222-4222-8222-222222222222",WRITE="33333333-3333-5333-8333-333333333333";
    static final String[] FLAGS={"inventory_acknowledged","work_accepted","new_work_allowed","resend_allowed","finalizer_allowed","key_removal","phone_released"};
    interface Action{void run()throws Exception;}
    static void denied(Action action)throws Exception {try{action.run();fail("unsafe reply accepted");}catch(VaultFailure expected){}}
    static NativePrivateCustodyReadback.Expected expected()throws Exception{return new NativePrivateCustodyReadback.Expected(OP,GEN,WRITE,"a".repeat(64),"b".repeat(64),"c".repeat(64),"d".repeat(64),"e".repeat(64),"f".repeat(64),0,24576);}
    static JSONObject row()throws Exception {var row=new JSONObject().put("schema","custodial.private-custody-chunk-readback.v1").put("state","OPAQUE_CHUNK_READ_ONLY_PENDING_RECONCILIATION")
        .put("operation_id",OP).put("generation_id",GEN).put("native_request_id",WRITE).put("request_body_sha256","a".repeat(64)).put("attestation_digest","b".repeat(64)).put("frame_sha256","c".repeat(64)).put("record_sha256","d".repeat(64)).put("plan_sha256","e".repeat(64)).put("chunk_sha256","f".repeat(64))
        .put("chunk_index",0).put("chunk_bytes",24576).put("received_at","2026-10-10T23:10:33.954956Z").put("frame_complete_syntax_verified",false);for(String k:FLAGS)row.put(k,false);return row;}
    static JSONObject wrapper(NativePrivateCustodyReadback.Mode mode)throws Exception {var data=new JSONObject().put("schema",mode==NativePrivateCustodyReadback.Mode.WRITE?"custodial.private-custody-write-result.v1":"custodial.private-custody-read-result.v1")
        .put("state",mode==NativePrivateCustodyReadback.Mode.WRITE?"OPAQUE_CHUNK_COMMIT_AND_EXACT_READBACK_ONLY_NOT_SEMANTIC_ACK":"EXACT_OPAQUE_CHUNK_READBACK_ONLY_NOT_SEMANTIC_ACK").put("readback",row());for(String k:FLAGS)data.put(k,false);
        if(mode==NativePrivateCustodyReadback.Mode.WRITE)data.put("current_transaction_private_writer_called",true).put("commit_readback_confirmed",true).put("original_request_readback_confirmed",true).put("ambiguous_write_reconciled",false).put("frame_complete_syntax_verified",false);
        else data.put("current_server_readback",true).put("write_outcome_unresolved",false);return new JSONObject().put("ok",true).put("data",data);}
    static byte[] bytes(JSONObject value){return value.toString().getBytes(StandardCharsets.UTF_8);}
    static NativePrivateCustodyReadback.Verified verify(JSONObject value,NativePrivateCustodyReadback.Mode mode)throws Exception{return NativePrivateCustodyReadback.verify(200,bytes(value),mode,expected());}
    @Test public void matchingWriteAndOriginalQueryAreHistoricalFieldsOnly()throws Exception {for(var mode:NativePrivateCustodyReadback.Mode.values()){var result=verify(wrapper(mode),mode);assertNotNull(result);assertEquals(mode,result.mode);assertEquals(WRITE,result.fields().get("native_request_id"));for(String flag:FLAGS)assertFalse(result.fields().getBoolean(flag));assertFalse(result.fields().getBoolean("frame_complete_syntax_verified"));}}
    @Test public void everyOriginalIdentityAndHashMustMatch()throws Exception {for(String key:new String[]{"operation_id","generation_id","native_request_id","request_body_sha256","attestation_digest","frame_sha256","record_sha256","plan_sha256","chunk_sha256"}){
        var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);value.getJSONObject("data").getJSONObject("readback").put(key,key.endsWith("id")?"44444444-4444-4444-8444-444444444444":"0".repeat(64));denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}}
    @Test public void noReplyCanUpgradeAnyAuthorityFlag()throws Exception {for(var mode:NativePrivateCustodyReadback.Mode.values())for(String flag:FLAGS)for(Object bad:new Object[]{true,"false",0,JSONObject.NULL})for(boolean nested:new boolean[]{false,true}){
        var value=wrapper(mode);(nested?value.getJSONObject("data").getJSONObject("readback"):value.getJSONObject("data")).put(flag,bad);denied(()->verify(value,mode));}}
    @Test public void completeSyntaxAndWrongCommitClaimsCannotBeCoerced()throws Exception {for(String key:new String[]{"current_transaction_private_writer_called","commit_readback_confirmed","original_request_readback_confirmed"})for(Object bad:new Object[]{false,"true",1,JSONObject.NULL}){
        var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);value.getJSONObject("data").put(key,bad);denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}
        for(boolean nested:new boolean[]{false,true}){var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);(nested?value.getJSONObject("data").getJSONObject("readback"):value.getJSONObject("data")).put("frame_complete_syntax_verified",true);denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}}
    @Test public void closedShapesRejectExtraMissingAndWrongWrapperFields()throws Exception {for(String level:new String[]{"top","data","row"}){var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);var target=level.equals("top")?value:level.equals("data")?value.getJSONObject("data"):value.getJSONObject("data").getJSONObject("readback");target.put("unknown_field","synthetic");denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}
        var missing=wrapper(NativePrivateCustodyReadback.Mode.WRITE);missing.getJSONObject("data").getJSONObject("readback").remove("received_at");denied(()->verify(missing,NativePrivateCustodyReadback.Mode.WRITE));var wrong=wrapper(NativePrivateCustodyReadback.Mode.WRITE);wrong.put("ok","true");denied(()->verify(wrong,NativePrivateCustodyReadback.Mode.WRITE));}
    @Test public void rawDuplicatesAndNonRFCJsonAreRefused()throws Exception {String value=wrapper(NativePrivateCustodyReadback.Mode.WRITE).toString();for(String bad:new String[]{value.substring(0,value.length()-1)+",\"ok\":true}",value+" trailing",value.replace("\"chunk_index\":0","\"chunk_index\":0,\"chunk_index\":0"),"{'ok':true}"})denied(()->NativePrivateCustodyReadback.verify(200,bad.getBytes(StandardCharsets.UTF_8),NativePrivateCustodyReadback.Mode.WRITE,expected()));}
    @Test public void chunkIntegerTypesValuesAndBoundariesAreExact()throws Exception {for(String key:new String[]{"chunk_index","chunk_bytes"})for(Object bad:new Object[]{"0",-1,0.5,Long.MAX_VALUE,JSONObject.NULL}){
        var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);value.getJSONObject("data").getJSONObject("readback").put(key,bad);denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}
        for(String token:new String[]{"0.0","0e0"}){String raw=wrapper(NativePrivateCustodyReadback.Mode.WRITE).toString().replace("\"chunk_index\":0","\"chunk_index\":"+token);denied(()->NativePrivateCustodyReadback.verify(200,raw.getBytes(StandardCharsets.UTF_8),NativePrivateCustodyReadback.Mode.WRITE,expected()));}
        denied(()->new NativePrivateCustodyReadback.Expected(OP,GEN,WRITE,"a".repeat(64),"b".repeat(64),"c".repeat(64),"d".repeat(64),"e".repeat(64),"f".repeat(64),0,24577));}
    @Test public void exactMicrosecondUtcTimeMustBeCalendarValid()throws Exception {for(String bad:new String[]{"2026-10-10T23:10:33.954Z","2026-02-30T23:10:33.954956Z","2026-10-10T23:10:33.954956+00:00","2026-10-10T23:10:60.954956Z","2026-10-10T23:10:33.954956z"}){
        var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);value.getJSONObject("data").getJSONObject("readback").put("received_at",bad);denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}}
    @Test public void unresolvedQueryAndNonSuccessStatusNeverCreateReadback()throws Exception {var data=new JSONObject().put("schema","custodial.private-custody-read-result.v1").put("state","NO_MATCHING_ORIGINAL_WRITE_READBACK").put("current_server_readback",false).put("write_outcome_unresolved",true);for(String flag:FLAGS)data.put(flag,false);
        var wrapper=new JSONObject().put("ok",true).put("data",data);assertNull(verify(wrapper,NativePrivateCustodyReadback.Mode.QUERY));assertNull(NativePrivateCustodyReadback.verify(503,new byte[0],NativePrivateCustodyReadback.Mode.WRITE,expected()));data.put("resend_allowed",true);denied(()->verify(wrapper,NativePrivateCustodyReadback.Mode.QUERY));}
    @Test public void ambiguousWriteIsAReportNotResendOrAcceptance()throws Exception {var value=wrapper(NativePrivateCustodyReadback.Mode.WRITE);value.getJSONObject("data").put("ambiguous_write_reconciled",true);var result=verify(value,NativePrivateCustodyReadback.Mode.WRITE);assertTrue(result.reportedAmbiguousWriteReconciled);for(String flag:FLAGS)assertFalse(result.fields().getBoolean(flag));
        value.getJSONObject("data").put("ambiguous_write_reconciled","true");denied(()->verify(value,NativePrivateCustodyReadback.Mode.WRITE));}
    @Test public void queryCannotSubstituteItsOwnNonceOrWrongMode()throws Exception {var value=wrapper(NativePrivateCustodyReadback.Mode.QUERY);value.getJSONObject("data").getJSONObject("readback").put("native_request_id","44444444-4444-5444-8444-444444444444");denied(()->verify(value,NativePrivateCustodyReadback.Mode.QUERY));denied(()->verify(wrapper(NativePrivateCustodyReadback.Mode.WRITE),NativePrivateCustodyReadback.Mode.QUERY));}
    @Test public void missingOversizedInvalidUtf8AndMutableProjectionsCannotAlterPins()throws Exception {denied(()->NativePrivateCustodyReadback.verify(200,null,NativePrivateCustodyReadback.Mode.WRITE,expected()));denied(()->NativePrivateCustodyReadback.verify(200,new byte[NativePrivateCustodyReadback.MAX_RESPONSE+1],NativePrivateCustodyReadback.Mode.WRITE,expected()));denied(()->NativePrivateCustodyReadback.verify(200,new byte[]{(byte)0xff},NativePrivateCustodyReadback.Mode.WRITE,expected()));
        var result=verify(wrapper(NativePrivateCustodyReadback.Mode.WRITE),NativePrivateCustodyReadback.Mode.WRITE);result.fields().put("key_removal",true);assertFalse(result.fields().getBoolean("key_removal"));}
    @Test public void retainedActualSqlRecordHasExactNativeDtoShapeButIsNotReexecuted()throws Exception {String source=System.getProperty("custodial.readback.actual.SQL.result");assertNotNull("exact retained SQL source input is required",source);var actual=new JSONObject(Files.readString(Path.of(source)));assertEquals("PASS",actual.get("status"));var row=actual.getJSONObject("write_result").getJSONObject("readback");
        var pins=new NativePrivateCustodyReadback.Expected(actual.getString("original_operation"),actual.getString("original_generation"),actual.getString("native_write_request"),actual.getString("write_body_sha256"),row.getString("attestation_digest"),row.getString("frame_sha256"),row.getString("record_sha256"),row.getString("plan_sha256"),row.getString("chunk_sha256"),row.getInt("chunk_index"),row.getInt("chunk_bytes"));
        for(var mode:NativePrivateCustodyReadback.Mode.values()){var data=actual.getJSONObject(mode==NativePrivateCustodyReadback.Mode.WRITE?"write_result":"query_result");var result=NativePrivateCustodyReadback.verify(200,bytes(new JSONObject().put("ok",true).put("data",data)),mode,pins);assertTrue(ProviderWireJson.same(row,result.fields()));}
    }
}
